using Microsoft.Data.Sqlite;
using NexaStation.Core;
using NexaStation.Domain;
using NexaStation.Infrastructure.Persistence;
using NexaStation.Providers.Emulation.Adapters;
using NexaStation.Providers.Emulation.Definitions;
using NexaStation.Providers.Emulation.Identification;
using NexaStation.Providers.Emulation.Launching;

namespace NexaStation.Providers.Emulation.Tests.Persistence;

public sealed class EmulationPersistenceTests
{
    [Fact] public async Task MigrationsSeedAllBuiltInPlatforms(){await using Context c=await Context.CreateAsync();Assert.Equal(16,(await c.Persistence.GetPlatformsAsync()).Count);}
    [Fact] public async Task AddsAndReadsInstallation(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);Assert.Equal(install.Id,(await c.Persistence.GetInstallationsAsync()).Single().Id);}
    [Fact] public async Task PreventsExactDuplicateAdapterPath(){await using Context c=await Context.CreateAsync();await c.Persistence.SaveInstallationAsync(c.Installation("custom","one"));await Assert.ThrowsAsync<SqliteException>(()=>c.Persistence.SaveInstallationAsync(c.Installation("custom","two")));}
    [Fact] public async Task AllowsMultipleBuildsAtDifferentPaths(){await using Context c=await Context.CreateAsync();await c.Persistence.SaveInstallationAsync(c.Installation("custom","one"));string second=Path.Combine(c.Root,"second.exe");File.WriteAllBytes(second,[0]);await c.Persistence.SaveInstallationAsync(c.Installation("custom","two") with{ExecutablePath=second,InstallationDirectory=c.Root});Assert.Equal(2,(await c.Persistence.GetInstallationsAsync()).Count);}
    [Fact] public async Task RelinksInstallationWithoutDeletingDependentGame(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);EmulatedGameImportResult imported=await c.ImportAsync(source,install.Id);string gameId=(await c.GameIdAsync())!;string replacement=Path.Combine(c.Root,"replacement.exe");File.WriteAllBytes(replacement,[1]);await c.Persistence.RelinkInstallationAsync(install.Id,replacement,new(true,"Fake","2.0",EmulatorCapability.DirectGameLaunch,["custom"],[]));Assert.NotNull(await c.Persistence.GetEmulatedGameAsync(gameId));Assert.Equal(replacement,(await c.Persistence.GetInstallationAsync(install.Id))!.ExecutablePath);Assert.Equal(1,imported.Added);}
    [Fact] public async Task DisableDoesNotDeleteGames(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);await c.ImportAsync(source,install.Id);await c.Persistence.SetInstallationEnabledAsync(install.Id,false);Assert.NotNull(await c.Persistence.GetEmulatedGameAsync((await c.GameIdAsync())!));Assert.False((await c.Persistence.GetInstallationAsync(install.Id))!.Enabled);}
    [Fact] public async Task ImportCreatesUnifiedLibraryItemProviderSourceAndEmulatorTarget(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);EmulatedGameImportResult result=await c.ImportAsync(source,install.Id);LibraryItem item=(await c.Library.QueryAsync(new(IncludeHidden:true))).Single();Assert.Equal(1,result.Added);Assert.Equal(ContentType.Game,item.ContentType);Assert.Equal("emulation",item.LaunchTarget!.ProviderId);Assert.Equal(LaunchType.Emulator,item.LaunchTarget.LaunchType);Assert.NotNull(item.LaunchTarget.EmulatedGameSourceId);}
    [Fact] public async Task ExactReimportUpdatesWithoutDuplication(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);await c.ImportAsync(source,install.Id);EmulatedGameImportResult second=await c.ImportAsync(source,install.Id);Assert.Equal(0,second.Added);Assert.Equal(1,second.Updated);Assert.Single(await c.Library.QueryAsync(new(IncludeHidden:true)));}
    [Fact] public async Task RelinkGamePreservesLibraryIdentityFavoriteAndHistory(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);await c.ImportAsync(source,install.Id);LibraryItem item=(await c.Library.QueryAsync(new(IncludeHidden:true))).Single();await c.Library.SetFavoriteAsync(item.Id,true);string replacement=Path.Combine(c.Root,"Relinked Homebrew.rom");File.WriteAllBytes(replacement,[5]);string gameId=item.LaunchTarget!.EmulatedGameSourceId!;await c.Persistence.RelinkGameAsync(gameId,replacement);LibraryItem after=(await c.Library.GetByIdAsync(item.Id))!;Assert.True(after.Favorite);Assert.Equal(item.Id,after.Id);Assert.Equal(replacement,(await c.Persistence.GetEmulatedGameAsync(gameId))!.GamePath);}
    [Fact] public async Task CancelledRefreshDoesNotMarkMissing(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);await c.ImportAsync(source,install.Id);string gameId=(await c.GameIdAsync())!;GameSourceScanResult cancelled=new(source,DateTime.UtcNow,DateTime.UtcNow,[],[],[],true,false);await c.Persistence.ApplyRefreshAsync(cancelled);Assert.True((await c.Persistence.GetEmulatedGameAsync(gameId))!.Available);}
    [Fact] public async Task SuccessfulCompleteRefreshMarksAbsentUnavailable(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);await c.ImportAsync(source,install.Id);string gameId=(await c.GameIdAsync())!;GameSourceScanResult complete=new(source,DateTime.UtcNow,DateTime.UtcNow,[],[],[],false,true);await c.Persistence.ApplyRefreshAsync(complete);Assert.False((await c.Persistence.GetEmulatedGameAsync(gameId))!.Available);}
    [Fact] public async Task RemovingEntryNeverDeletesExternalGame(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);await c.ImportAsync(source,install.Id);LibraryItem item=(await c.Library.QueryAsync(new(IncludeHidden:true))).Single();await c.Library.DeleteAsync(item.Id);Assert.True(File.Exists(c.GamePath));}
    [Fact] public async Task PerGameEmulatorSelectionPersists(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(null);await c.ImportAsync(source,null);string gameId=(await c.GameIdAsync())!;await c.Persistence.SetPreferredEmulatorAsync(gameId,install.Id);Assert.Equal(install.Id,(await c.Persistence.GetEmulatedGameAsync(gameId))!.PreferredEmulatorInstallationId);}
    [Fact] public async Task ResolverReturnsSafeStructuredLaunch(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom") with{ArgumentsOverride="{EMULATOR_PATH} --game {GAME_PATH}"};await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);await c.ImportAsync(source,install.Id);IEmulatorAdapter adapter=new CustomEmulatorAdapter(new NoProbe(),new FilenameGameIdentifier());EmulatorLaunchResolver resolver=new(c.Persistence,new EmulatorAdapterRegistry([adapter]));ResolvedLaunchTarget resolved=await resolver.ResolveAsync(new((await c.GameIdAsync())!));Assert.Equal(LaunchType.Executable,resolved.LaunchTarget.LaunchType);Assert.Equal(["--game",c.GamePath],resolved.LaunchTarget.ArgumentList);Assert.Null(resolved.LaunchTarget.Arguments);}
    [Fact] public async Task ResolverRejectsUnavailablePreferredWithoutConfirmation(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom") with{ArgumentsOverride="{EMULATOR_PATH} {GAME_PATH}"};await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);await c.ImportAsync(source,install.Id);string gameId=(await c.GameIdAsync())!;File.Delete(install.ExecutablePath);IEmulatorAdapter adapter=new CustomEmulatorAdapter(new NoProbe(),new FilenameGameIdentifier());EmulatorLaunchResolver resolver=new(c.Persistence,new EmulatorAdapterRegistry([adapter]));await Assert.ThrowsAsync<InvalidOperationException>(()=>resolver.ResolveAsync(new(gameId)));}
    [Fact] public async Task IdentityRepairPersistsSerialAndPreservesUserEditedTitle(){await using Context c=await Context.CreateAsync();EmulatorInstallation install=c.Installation("custom");await c.Persistence.SaveInstallationAsync(install);GameSource source=await c.SaveSourceAsync(install.Id);await c.ImportAsync(source,install.Id);LibraryItem item=(await c.Library.QueryAsync(new(IncludeHidden:true))).Single();GameIdentificationResult identified=new("God of War II",Path.GetFileName(c.GamePath),"SCUS-97481","USA",null,1,1,GameIdentificationConfidence.DiscSerial,[]);Assert.True(await c.Persistence.ApplyIdentificationRepairAsync(item.Id,identified,"Homebrew Adventure"));Assert.Equal("God of War II",(await c.Library.GetByIdAsync(item.Id))!.Title);Assert.Equal("SCUS-97481",(await c.Persistence.GetEmulatedGameAsync((await c.GameIdAsync())!))!.GameIdentifier);await using(SqliteConnection connection=await c.Factory.OpenAsync()){await using SqliteCommand command=connection.CreateCommand();command.CommandText="UPDATE LibraryItems SET Title='My Custom Title',SortTitle='Homebrew Adventure' WHERE Id=$id;";command.Parameters.AddWithValue("$id",item.Id);await command.ExecuteNonQueryAsync();}Assert.False(await c.Persistence.ApplyIdentificationRepairAsync(item.Id,identified,"Homebrew Adventure"));Assert.Equal("My Custom Title",(await c.Library.GetByIdAsync(item.Id))!.Title);}

    private sealed class NoProbe:IEmulatorCapabilityProbe{public Task<EmulatorProbeResult> ProbeAsync(string executablePath,EmulatorProbeOptions options,CancellationToken cancellationToken=default)=>Task.FromResult(new EmulatorProbeResult(false,null,null,EmulatorCapability.None,[],[]));}

    private sealed class Context:IAsyncDisposable
    {
        private Context(string root,SqliteConnectionFactory factory){Root=root;Factory=factory;Persistence=new(factory);Library=new(factory);ExecutablePath=Path.Combine(root,"fake.exe");GamePath=Path.Combine(root,"Homebrew Adventure.rom");File.WriteAllBytes(ExecutablePath,[0]);File.WriteAllBytes(GamePath,[1,2,3]);}
        public string Root{get;}public string ExecutablePath{get;}public string GamePath{get;}public SqliteConnectionFactory Factory{get;}public SqliteEmulationPersistence Persistence{get;}public SqliteLibraryRepository Library{get;}
        public static async Task<Context>CreateAsync(){string root=Path.Combine(Path.GetTempPath(),"NexaStation.Emu.Db."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Context context=new(root,new SqliteConnectionFactory(Path.Combine(root,"test.db")));await new DatabaseInitializer(context.Factory,new NullLogger()).InitializeAsync();return context;}
        public EmulatorInstallation Installation(string adapter,string id="emu")=>new(){Id=id,AdapterId=adapter,DisplayName=id,ExecutablePath=ExecutablePath,InstallationDirectory=Root,Enabled=true,ValidationStatus=EmulatorValidationStatus.ProbeFailed,DetectedCapabilities=EmulatorCapability.DirectGameLaunch,AddedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow};
        public async Task<GameSource> SaveSourceAsync(string? emulator){GameSource source=new(){Id="source",Name="Custom Games",FolderPath=Root,PlatformId="custom",AdapterPreferenceId=emulator,Enabled=true,IncludeSubfolders=true,CreatedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow};await Persistence.SaveGameSourceAsync(source);return source;}
        public Task<EmulatedGameImportResult> ImportAsync(GameSource source,string? emulator){FileInfo file=new(GamePath);GameIdentificationResult identification=new("Homebrew Adventure",file.Name,null,null,null,null,null,GameIdentificationConfidence.FilenameOnly,[]);DiscoveredGame game=new("custom",GamePath,Path.GetFullPath(GamePath).ToUpperInvariant(),"Homebrew Adventure",file.Name,file.Extension,file.Length,file.LastWriteTimeUtc,identification,PreferredEmulatorInstallationId:emulator);return Persistence.ImportAsync(source,[new(game,true)]);}
        public async Task<string?> GameIdAsync(){await using SqliteConnection connection=await Factory.OpenAsync();await using SqliteCommand command=connection.CreateCommand();command.CommandText="SELECT Id FROM EmulatedGameSources LIMIT 1;";return await command.ExecuteScalarAsync() as string;}
        public ValueTask DisposeAsync(){try{Directory.Delete(Root,true);}catch(IOException){}return ValueTask.CompletedTask;}
    }
    private sealed class NullLogger:IAppLogger{public void Information(string eventName,string message,IReadOnlyDictionary<string,object?>? properties=null){}public void LogError(string eventName,string message,Exception? exception=null,IReadOnlyDictionary<string,object?>? properties=null){}}
}
